/* Session 10 – Context APITopics to Cover:Global state management.useContext hook.Demo:Theme toggle (dark/light mode). */

import React, { useContext, useState } from 'react'
import UserContext from './UserContext'
import Navbar from './Navbar';
import ThemeContext from './ThemeContext';
import Parent from './Parent';
import NotificationContext from './NotificationContext';

function Session10() {
  const user = useContext(UserContext);
  const [theme, setTheme] = useState("light");

  const toggleTheme = () => {setTheme((currentTheme) => currentTheme === "light" ? "dark" : "light");};

  const mainStyle = {minHeight: "50vh",padding: "20px",backgroundColor: theme === "light" ? "#ffffff" : "#222222",color: theme === "light" ? "#222222" : "#ffffff",};

  // const theme="dark";

  //5th task variables
  const {notificationCount,addNotification,clearNotifications,} = useContext(NotificationContext);

  return (
    <div>
      <UserContext.Provider value={user}>
        <ThemeContext.Provider value={{ theme }}>
          <div style={mainStyle}>
            <Navbar />

            <button onClick={toggleTheme}>
              Switch to {theme === "light" ? "dark" : "light"} mode
            </button>

            <Parent />
          </div>
        </ThemeContext.Provider>
      </UserContext.Provider><br/><br/>


      <h2>Notifications</h2>

      <p>Unread messages: {notificationCount}</p>

      <button onClick={addNotification}>
        New Message
      </button>

      <button onClick={clearNotifications}>
        Clear Notifications
      </button>
    </div>
  );
}

export default Session10
